+                    break;
+                default:
+                    type = CQL3Type.Raw.from(Enum.<CQL3Type.Native>valueOf(CQL3Type.Native.class, dt.getName().toString().toUpperCase()));
+                    break;
+            }
+            if (dt.isFrozen()) {
+                type = CQL3Type.Raw.frozen(type);
